    rows = load_station_rows()
    append_to_master(rows)
    write_audit_entry(len(rows), sorted(glob.glob(os.path.join(FIELD_DIR, "*.csv"))))
    print(f"Imported {len(rows)} records in batch {BATCH_ID}; audit entry written")


if __name__ == "__main__":
    main()

